import sys

def solve(n, m, a, b):
    grid = [['.' for _ in range(m)] for _ in range(n)]

    def can_place(row, col, length):
        if col + length > m:
            return False
        for i in range(length):
            if grid[row][col + i] == '*':
                return False
        return True

    def place(row, col, length):
        for i in range(length):
            grid[row][col + i] = '*'

    def backtrack(row, col):
        if row == n:
            return True
        if col == m:
            return backtrack(row + 1, 0)

        if grid[row][col] != '.':
            return backtrack(row, col + 1)

        if a[row] == 0:
            for i in range(col, m):
                grid[row][i] = '.'
            return backtrack(row + 1, 0)

        for length in range(1, m - col + 1):
            if can_place(row, col, length):
                place(row, col, length)
                new_col = col + length + 1
                if backtrack(row, new_col):
                    return True
                for i in range(length):
                    grid[row][col + i] = '.'

        return False

    backtrack(0, 0)

    for line in grid:
        print(''.join(line))

def main():
    import sys
    input = sys.stdin.read().split()
    n, m = map(int, input[:2])
    a = list(map(int, input[2:2+n]))
    b = list(map(int, input[2+n:]))
    solve(n, m, a, b)

main()
